using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace CFEditor {
static class CFInstallChecks {
 sealed class Service:ICFInstallTransport {
  public bool Closed{get;set;}public byte[] OfficialFirmware{get;set;}public int Product=2424833,Count=12,Installs;public bool LostReceipt,ForbidBackup;public readonly List<string> Steps=new List<string>();
  public Service(){Closed=true;}public Task<string> Status(Action<string> log){Steps.Add("status");return Task.FromResult("connected=True; name=Catalyst 60\nFull device synchronization confirmed\nshutdown complete");}
  public Task<string> Backup(string folder,Action<string> log){if(ForbidBackup)throw new Exception("Unsafe firmware upgrade attempted a fresh preset scan");Steps.Add("backup");Directory.CreateDirectory(folder);return Task.FromResult("shutdown complete");}
  public int CreateBackup(string folder,string archive){Steps.Add("archive");File.WriteAllText(archive,"synthetic backup fixture");var reads=Enumerable.Range(1,12).Select(i=>{string first="preset-"+i.ToString("00")+"-read-1.catl6p",second="preset-"+i.ToString("00")+"-read-2.catl6p";File.WriteAllText(Path.Combine(folder,first),"preset "+i);File.WriteAllText(Path.Combine(folder,second),"preset "+i);string digest=FirmwareCodec.Hash(File.ReadAllBytes(Path.Combine(folder,first)));return new{index=i,first,second,first_sha256=digest,second_sha256=digest,data_sha256=digest};}).ToArray();File.WriteAllText(archive+".verification.json",new JavaScriptSerializer().Serialize(new{schema="CatalystIR.RepeatedPresetReads.v1",archive_sha256=FirmwareCodec.Hash(File.ReadAllBytes(archive)),reads}));return Count;}
  public int VerifyBackup(string archive){Steps.Add("verify");Need(File.Exists(archive)&&File.Exists(archive+".verification.json"),"verification evidence absent");for(int i=1;i<=12;i++)foreach(int j in new[]{1,2})Need(File.Exists(Path.Combine(Path.GetDirectoryName(archive),"preset-"+i.ToString("00")+"-read-"+j+".catl6p")),"repeated preset read absent");return Count;}public int BackupProduct(string archive){Steps.Add("identity");return Product;}
  public Task<string> Install(string image,string backup,string hash,Func<string,bool> accept,Action<string> log){Steps.Add("install");Installs++;if(!File.Exists(backup)||!accept("install:"+hash)||accept("install:"+new string('0',64)))throw new Exception("install guard failed");return Task.FromResult((LostReceipt?"":"INSTALL_REQUEST_CONFIRMED\n")+"UPDATE_ENGINE_COMPLETED; VERIFY_DEVICE_BOOT_SEPARATELY\nshutdown complete");}
 }
 static void Need(bool b,string name){if(!b)throw new Exception(name);}static bool Refused(Func<Task> action){try{action().GetAwaiter().GetResult();return false;}catch(IOException){return true;}}
 static void UpgradeChecks(CFPreparedPackage package,byte[] official,string sourceRoot,string journal,List<string> checks){
  var installed=CFInstallRecord.Load(journal);var pinned=CFUpgradeBackup.Resolve(sourceRoot,installed.Product,installed.Edition);Need(pinned.Archive==installed.Backup&&pinned.ArchiveHash==FirmwareCodec.Hash(File.ReadAllBytes(installed.Backup)),"matching active backup not selected");
  int leases=0;FakeAssetLease lease=null;var service=new Service{OfficialFirmware=official,ForbidBackup=true};var installer=new CFInstallCoordinator(()=>{leases++;return lease=new FakeAssetLease();},()=>service,p=>true,b=>Need(FirmwareCodec.Hash(b)==package.Hash,"upgrade image changed"));
  string wrongEdition=installed.Edition.Substring(0,63)+(installed.Edition[63]=='A'?'B':'A');
  Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,wrongEdition,null))&&leases==0&&service.Steps.Count==0,"same-model / same-prefix but different edition opened transport");
  Need(Refused(()=>installer.Upgrade(package,2424834,sourceRoot,installed.Edition,null))&&leases==0,"different product backup selected");
  Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition.Substring(0,12),null))&&leases==0,"short public label accepted instead of full live edition");
  string firstRead=Path.Combine(Path.GetDirectoryName(installed.Backup),"preset-01-read-1.catl6p");byte[] read=File.ReadAllBytes(firstRead);File.Delete(firstRead);
  try{Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition,null))&&leases==0,"partial repeated reads opened transport");}finally{File.WriteAllBytes(firstRead,read);}
  File.WriteAllText(firstRead,"changed repeated read");try{Need(Refused(()=>installer.Install(package,installed.Product,sourceRoot,null,pinned.Archive,pinned))&&leases==0,"pinned read changed before lease acquisition");}finally{File.WriteAllBytes(firstRead,read);}
  foreach(string file in new[]{installed.Candidate,installed.Backup}){byte[] original=File.ReadAllBytes(file),changed=(byte[])original.Clone();changed[0]^=1;File.WriteAllBytes(file,changed);try{Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition,null))&&leases==0,"changed firmware/archive hash opened transport");}finally{File.WriteAllBytes(file,original);}}
  installed.Phase="failed";installed.Save(journal);try{Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition,null))&&leases==0,"unconfirmed installation supplied a backup");}finally{installed.Phase="active";installed.Save(journal);}
  string duplicate=Path.Combine(sourceRoot,"backups","duplicate-edition-fixture");Directory.CreateDirectory(duplicate);new CFInstallRecord{Product=installed.Product,Phase="active",Folder=duplicate,Candidate=Path.Combine(duplicate,"Catalyst-CF.ctf"),Hash=installed.Hash,Backup=Path.Combine(duplicate,"presets","Catalyst-verified.catl6a"),Edition=installed.Edition}.Save(Path.Combine(duplicate,"installation.json"));
  try{Need(Refused(()=>installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition,null))&&leases==0,"ambiguous edition selected an arbitrary backup");}finally{File.Delete(Path.Combine(duplicate,"installation.json"));Directory.Delete(duplicate);}
  checks.Add("unsafe-CF upgrade rejects wrong full edition even with equal display prefix, wrong model, missing/changed reads, candidate/archive hash changes, unconfirmed or ambiguous records before lease/SDK acquisition");
  var upgraded=installer.Upgrade(package,installed.Product,sourceRoot,installed.Edition,null).GetAwaiter().GetResult();Need(leases==1&&lease.Released==1&&service.Installs==1&&!service.Steps.Contains("backup")&&!service.Steps.Contains("archive")&&upgraded.BackupSourceEdition==installed.Edition&&upgraded.BackupHash==pinned.ArchiveHash,"exact-edition upgrade performed a fresh preset scan or lost its source binding");pinned.ValidateCopy(upgraded.Backup);
  checks.Add("matching active exact-edition upgrade reuses the hash-pinned 12-preset archive and all 24 reads; transport cannot invoke fresh backup or preset selection; copied evidence revalidated");
 }
 public static void Run(string packagePath,string officialPath,string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var bytes=File.ReadAllBytes(packagePath);var edition=Enumerable.Range(0,32).Select(i=>(byte)(i+1)).ToArray();var package=new CFPreparedPackage(bytes,edition,5);var official=File.ReadAllBytes(officialPath);int opens=0;FakeAssetLease lease=null;var service=new Service{OfficialFirmware=official};Action<byte[]> validator=b=>Need(FirmwareCodec.Hash(b)==package.Hash,"candidate modified");
  byte first=package.Bytes[0],firstEdition=package.Edition[0];bytes[0]^=1;edition[0]^=1;var exposed=package.Bytes;exposed[0]^=2;var exposedEdition=package.Edition;exposedEdition[0]^=2;Need(package.Bytes[0]==first&&package.Edition[0]==firstEdition&&FirmwareCodec.Hash(package.Bytes)==package.Hash,"prepared package aliases caller memory");checks.Add("caller arrays and exported snapshots cannot mutate the prepared firmware or its edition");
  string export=Path.Combine(folder,"export.ctf");File.WriteAllText(export,"existing local export");using(var locked=new FileStream(export,FileMode.Open,FileAccess.Read,FileShare.None)){Need(Refused(()=>Task.Run(()=>package.Export(export))),"locked export was replaced");}Need(File.ReadAllText(export)=="existing local export"&&Directory.GetFiles(folder,"*.tmp").Length==0,"failed export damaged existing data or left a partial file");package.Export(export);Need(FirmwareCodec.Hash(File.ReadAllBytes(export))==package.Hash,"export mismatch");checks.Add("verified atomic export preserves an existing file on sharing failure and leaves no partial firmware");
  var no=new CFInstallCoordinator(()=>{opens++;return lease=new FakeAssetLease();},()=>service,p=>false,validator);Need(Refused(()=>no.Install(package,2424833,Path.Combine(folder,"disabled"),null))&&opens==0&&service.Steps.Count==0,"unapproved candidate opened transport");checks.Add("unapproved initial motor rejected before opening a lease or SDK");
  var job=new CFInstallCoordinator(()=>{opens++;return lease=new FakeAssetLease();},()=>service,p=>true,validator);string success=Path.Combine(folder,"success");var result=job.Install(package,2424833,success,null).GetAwaiter().GetResult();Need(lease.Released==1&&result.Phase=="awaiting-reboot"&&service.Installs==1&&service.Steps.SequenceEqual(new[]{"status","backup","archive","verify","identity","install"}),"initial workflow order/lease");Need(File.Exists(Path.Combine(result.Folder,"Catalyst-OFICIAL-recuperacion.ctf")),"recovery firmware absent");checks.Add("sync, verified 12-preset product backup, recovery copy and exact-image install; lease released before result");
  Need(Refused(()=>job.Install(package,2424833,success,null))&&service.Installs==1,"pending installation repeated");checks.Add("pending reboot or uncertain transfer cannot silently start a second installation");string journal=Path.Combine(result.Folder,"installation.json"),identity="CFCX-UID2:10203040A0B0C0D0:"+result.Edition;
  service=new Service{OfficialFirmware=official};job=new CFInstallCoordinator(()=>lease=new FakeAssetLease(),()=>service,p=>true,validator);var reused=job.Install(package,2424833,Path.Combine(folder,"reuse"),null,result.Backup).GetAwaiter().GetResult();Need(service.Installs==1&&!service.Steps.Contains("backup")&&!service.Steps.Contains("archive")&&File.ReadAllBytes(reused.Backup).SequenceEqual(File.ReadAllBytes(result.Backup))&&lease.Released==1,"existing backup was not reused intact without another device backup");checks.Add("explicit existing backup is product/count verified and reused byte-exactly without another device preset read");
  service=new Service{OfficialFirmware=official,Product=2424834};job=new CFInstallCoordinator(()=>lease=new FakeAssetLease(),()=>service,p=>true,validator);Need(Refused(()=>job.Install(package,2424833,Path.Combine(folder,"reuse-wrong-model"),null,result.Backup))&&service.Installs==0&&!service.Steps.Contains("backup")&&lease.Released==1,"wrong existing backup reached updater");checks.Add("wrong-model existing backup refuses update without creating a replacement device backup");
  bool refused=false;try{CFInstallCoordinator.ConfirmBoot(journal,2424834,identity);}catch(IOException){refused=true;}Need(refused,"wrong product boot confirmed");refused=false;try{CFInstallCoordinator.ConfirmBoot(journal,2424833,identity.Substring(0,27)+new string('F',64));}catch(IOException){refused=true;}Need(refused,"wrong CF edition boot confirmed");Need(CFInstallCoordinator.ConfirmBoot(journal,2424833,identity).Phase=="active","verified boot not recorded");checks.Add("fresh receiver product and exact CF edition required before confirming startup");
  UpgradeChecks(package,official,success,journal,checks);
  service=new Service{OfficialFirmware=official,Product=2424834};lease=null;job=new CFInstallCoordinator(()=>lease=new FakeAssetLease(),()=>service,p=>true,validator);Need(Refused(()=>job.Install(package,2424833,Path.Combine(folder,"wrong-model"),null))&&service.Installs==0&&lease.Released==1,"backup product mismatch reached updater");checks.Add("different model backup fails before update; confirmed closure releases lease");
  service=new Service{OfficialFirmware=official,Count=11};lease=null;job=new CFInstallCoordinator(()=>lease=new FakeAssetLease(),()=>service,p=>true,validator);Need(Refused(()=>job.Install(package,2424833,Path.Combine(folder,"incomplete-backup"),null))&&service.Installs==0,"partial backup reached updater");checks.Add("incomplete preset backup cannot reach update");
  service=new Service{OfficialFirmware=official,LostReceipt=true};lease=null;job=new CFInstallCoordinator(()=>lease=new FakeAssetLease(),()=>service,p=>true,validator);string lost=Path.Combine(folder,"lost");Need(Refused(()=>job.Install(package,2424833,lost,null))&&service.Installs==1&&lease.Released==1,"missing transfer receipt");var recorded=CFInstallRecord.Load(Directory.GetFiles(Path.Combine(lost,"backups"),"installation.json",SearchOption.AllDirectories).Single());Need(recorded.Phase=="transfer-uncertain"&&Refused(()=>job.Install(package,2424833,lost,null))&&service.Installs==1,"uncertain update repeated");checks.Add("missing transfer receipt stays uncertain, retains journal and blocks repeat without reflash");
  File.WriteAllText(Path.Combine(folder,"result.json"),new JavaScriptSerializer().Serialize(new{passed=true,USB_opened=false,SDK_loaded=false,device_enumeration=false,native_driver_called=false,checks=checks.ToArray()}));
 }
}
}
